function renderScanBanner(){const active=scanSubmitting||scanProgress?.status==='running';$('scanBanner').hidden=!active;if(!active)return;const elapsed=Math.floor((Date.now()-(scanStartedAt||scanProgress?.startedAt||Date.now()))/1000);$('scanElapsed').textContent='已用 '+elapsed+' 秒';const enumerating=!scanProgress||scanProgress.phase==='枚举文件';$('scanBannerTitle').textContent=enumerating?'正在发现音乐文件…':'正在读取音乐元信息…';$('scanBannerCounts').textContent=scanProgress?(enumerating?'已发现 '+scanProgress.total+' 个音乐文件':`已读取 ${scanProgress.completed} / ${scanProgress.total} · 失败 ${scanProgress.failed} · ${scanProgress.total?Math.floor(scanProgress.completed/scanProgress.total*100):100}%`):'扫描已提交，正在读取目录…';$('scanBannerFile').textContent=(scanProgress?.current||'')+' · 完成后更新列表';if(enumerating)$('scanBannerProgress').removeAttribute('value');else $('scanBannerProgress').value=scanProgress.total?scanProgress.completed/scanProgress.total*100:100}
