function renderOverlayWaveform(){const cards=[...$('duplicateVersions').children],left=cards.find(c=>c.dataset.duplicateTrack===$('duplicateLeft').value),right=cards.find(c=>c.dataset.duplicateTrack===$('duplicateRight').value);if(!left?.waveData||!right?.waveData)return;const box=$('duplicateWaveOverlay');box.waveSources=[left.waveData,right.waveData];box.waveDuration=Math.max(left.waveData.duration,right.waveData.duration);box.waveRenderKey=null;waveStart=waveRestoreStart??0;waveRestoreStart=null;updateWaveViewport();const seek=async time=>{const group=duplicateGroups[duplicateGroupIndex],ids=[$('duplicateLeft').value,$('duplicateRight').value],track=group.find(t=>t.id===(ids.includes(playing?.track.id)?playing.track.id:ids[0]));await auditionDuplicate(track);if(!playing)return;const end=Math.min(...group.filter(t=>ids.includes(t.id)).map(t=>t.duration));seekPlayback(Math.max(0,Math.min(end-.05,time)))};box.onclick=e=>{const bounds=box.getBoundingClientRect();seek(waveStart+(e.clientX-bounds.left)/bounds.width*Math.min(waveSeconds,box.waveDuration)).catch(e=>log(e.message))};box.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();seek(playbackTime()+(e.key==='ArrowLeft'?-1:1)).catch(e=>log(e.message))}}}
