$('waveZoom').onchange=()=>zoomWave(Number($('waveZoom').value));const waveSizes=[1,1.5,3,5,6,10,15,30];$('waveZoomIn').onclick=()=>zoomWave([...waveSizes].reverse().find(s=>s<waveSeconds)||1);$('waveZoomOut').onclick=()=>zoomWave(waveSizes.find(s=>s>waveSeconds)||30);$('waveFollow').onchange=updateWaveViewport;for(const [id,direction]of [['waveEarlier',-1],['waveLater',1]])$(id).onclick=()=>{$('waveFollow').checked=false;waveStart+=direction*waveSeconds*.5;updateWaveViewport()};

