function pauseLyricBrowsing(box){if(!box)return;box.scrollTo({top:box.scrollTop,behavior:'auto'});scheduleLyricResume(box)}
document.addEventListener('wheel',e=>pauseLyricBrowsing(lyricScrollContainer(e.target)),{capture:true,passive:true});document.addEventListener('pointerdown',e=>{const box=lyricScrollContainer(e.target);if(box&&(e.pointerType==='touch'||e.clientX>=box.getBoundingClientRect().right-18))pauseLyricBrowsing(box)},{capture:true,passive:true});document.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','PageUp','PageDown','Home','End'].includes(e.key))pauseLyricBrowsing(lyricScrollContainer(e.target))},true);

document.addEventListener('scroll',e=>{const box=e.target;if(box instanceof Element&&box.matches('.candidate-lyrics,.duplicate-lyrics,#lyricLines')&&lyricTimeline.isFollowPaused(box))scheduleLyricResume(box)},true);document.addEventListener('touchmove',e=>pauseLyricBrowsing(lyricScrollContainer(e.target)),{capture:true,passive:true});

let overrideTrackId=null,overrideLoading=0;
const overrideLabels={title:'歌名',artist:'歌手',album:'专辑',lyrics:'歌词',album_artist:'专辑歌手',date:'发行日期',genre:'流派',track:'曲目编号',disc:'碟片编号',composer:'作曲',comment:'备注',language:'语种',copyright:'版权'};
function addOverrideRow(key,value='',enabled=false,base=''){const row=element('div',undefined,'override-row'),label=element('label'),check=document.createElement('input');check.type='checkbox';check.checked=enabled;const name=document.createElement('input');name.value=key;name.placeholder='字段名，如 composer';name.setAttribute('aria-label','覆盖字段名');if(overrideLabels[key])name.readOnly=true;const input=document.createElement(key==='lyrics'?'textarea':'input');input.value=enabled?value:base;input.disabled=!enabled;input.setAttribute('aria-label',overrideLabels[key]||key||'覆盖值');check.onchange=()=>{input.disabled=!check.checked};label.append(check,element('span',overrideLabels[key]||'自定义'));const hint=element('small',base?'当前默认：'+base.slice(0,100):'当前默认：空','hint');row.append(label,name,input,hint);row.overrideControls={check,name,input};$('overrideFields').append(row)}
async function openOverrides(id){const request=++overrideLoading;overrideTrackId=id;$('overridePanel').hidden=false;$('overrideBackdrop').hidden=false;$('overrideFields').replaceChildren();$('overrideMessage').textContent='正在加载最终输出信息…';$('saveOverrides').disabled=true;try{const response=await fetch('/api/track?id='+encodeURIComponent(id));if(!response.ok)throw Error('读取歌曲失败');const t=await response.json();if(request!==overrideLoading)return;const map=t.manualOverrides||{},preview=t.exportPreview||{},choice=t.metadataResult?.candidates?.find(c=>c.id===preview.candidateId&&c.source===preview.source),base={...t,...(preview.origin==='original'?t.originalMetadata||{}:choice||{})};$('overrideSong').textContent=t.title+' · '+t.artist;for(const key of new Set([...Object.keys(overrideLabels),...Object.keys(map)]))addOverrideRow(key,map[key],Object.hasOwn(map,key),String(base[key]??''));window.metadataEditor?.mountOverrideCover(t);$('overrideMessage').textContent='未勾选的字段沿用候选或原信息，保存后在最终导出选择列显示。';locks();$('closeOverrides').focus()}catch(e){$('overrideMessage').textContent=e.message}}
function closeOverrides(){overrideLoading++;$('overridePanel').hidden=true;$('overrideBackdrop').hidden=true;afterDialogLayout(()=>{if(!$('detailPanel').hidden)($('metadataAdvanced')&&detailRegion==='metadata'?$('metadataAdvanced'):$('editOverrides')).focus();else if(!topDialog())$('query').focus()})}
$('editOverrides').onclick=()=>{if(selectedId)openOverrides(selectedId)};$('closeOverrides').onclick=closeOverrides;$('overrideBackdrop').onclick=closeOverrides;$('addOverrideField').onclick=()=>addOverrideRow('','',true);
async function persistOverrides(values){const id=overrideTrackId;await api('manual-overrides',{id,overrides:values});await syncState();if(selectedId===id)await openDetail(id,detailRegion);$('overrideMessage').textContent=Object.keys(values).length?'覆盖已保存，最终输出将优先使用这些字段。':'全部覆盖已清除，已恢复默认导出规则。';}
$('saveOverrides').onclick=()=>task(async()=>{const values={};for(const row of $('overrideFields').children){const {check,name,input}=row.overrideControls;if(!check.checked)continue;const key=name.value.trim();if(!key)throw Error('请填写自定义字段名');if(Object.hasOwn(values,key))throw Error('字段重复：'+key);Object.defineProperty(values,key,{value:input.value,enumerable:true})}await persistOverrides(values)});$('clearOverrides').onclick=()=>task(async()=>{await persistOverrides({});await openOverrides(overrideTrackId);$('overrideMessage').textContent='全部覆盖已清除。'});
document.addEventListener('keydown',e=>{if(!$('overridePanel').hidden&&e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeOverrides()}},true);

let nativeStatusPending=false;
async function refreshNativePlayback(){if(!nativePlayback||!playing||nativeStatusPending||!window.desktop.player.status)return;nativeStatusPending=true;try{const request=playRequest,revision=nativeRevision,state=await window.desktop.player.status();if(request===playRequest&&revision===nativeRevision)applyNativeState(state)}catch{}finally{nativeStatusPending=false}}
setInterval(refreshNativePlayback,500);
async function nativeCommand(command){const revision=nativeRevision,result=await command();if(nativeRevision===revision)nativeState=result;return nativeState}
async function activateTrackPlayback(track,showPlayer=false,buttonId='mpvPause'){if(!track)return;const loaded=nativePlayback?nativeState.loaded:$('audioPlayer').readyState>0;if(playing?.track.id===track.id&&playing.segmentIndex===null&&loaded)return togglePlaybackPause(buttonId);return playTrack(track,null,null,showPlayer)}
async function activateDuplicatePlayback(track){if(!track)return;const loaded=nativePlayback?nativeState.loaded:$('audioPlayer').readyState>0;if(playing?.track.id===track.id&&playing.segmentIndex===null&&loaded)return togglePlaybackPause('duplicatePause');return auditionDuplicate(track)}
function syncPlaybackButtons(){const audio=$('audioPlayer'),loaded=nativePlayback?nativeState.loaded:audio.readyState>0&&!audio.ended,paused=nativePlayback?nativeState.paused:audio.paused,current=playing?.segmentIndex===null?playing.track.id:null;for(const row of $('rows').querySelectorAll('[data-track-id]')){const active=!!playing&&loaded&&row.dataset.trackId===String(playing.track.id);row.classList.toggle('now-playing',active);row.classList.toggle('playback-paused',active&&paused);if(active)row.setAttribute('aria-current','true');else row.removeAttribute('aria-current')}const group=duplicateGroups[duplicateGroupIndex];if(group){for(const [id,select,caption]of [['duplicateSwitchLeft','duplicateLeft','左侧 A'],['duplicateSwitchRight','duplicateRight','右侧 B']]){$(id).dataset.playTrack=$(select).value;$(id).dataset.playCaption=caption}}for(const button of document.querySelectorAll('[data-play-track]')){const action=musicLibrary.playbackAction(button.dataset.playTrack,current,loaded,paused),caption=button.dataset.playCaption||'',text=action.icon+(button.dataset.playIconOnly?'':' '+action.label+(caption?' · '+caption:''));if(button.textContent!==text)button.textContent=text;button.setAttribute('aria-label',action.label+(caption?' · '+caption:''));button.title=action.label+(caption?' · '+caption:'');button.disabled=pauseChanging||button.dataset.loading==='true';}if(nativePlayback&&playing)updatePauseButton('mpvPause',paused,pauseChanging)}
for(const type of ['playing','play','pause','ended','error','emptied','loadedmetadata'])$('audioPlayer').addEventListener(type,syncPlaybackButtons);

// Measure occupied space rather than assuming one fixed player or window size.
const dialogIds=['overridePanel','settings','lyricPlayer','duplicatePanel','detailPanel'];
function afterDialogLayout(callback){requestAnimationFrame(()=>requestAnimationFrame(callback))}
function topDialog(){return dialogIds.map($).find(panel=>!panel.hidden)}
const exportOptions=document.createElement('div');exportOptions.className='export-options';exportOptions.setAttribute('role','group');exportOptions.setAttribute('aria-label','导出规则与手动覆盖');
const popupTrack=document.querySelector('.popup-track');
for(const id of ['editOverrides','candidateExportMode','excludeTrack','candidateExportHint','excludeTrackHint'])exportOptions.append($(id));
popupTrack.append(exportOptions);
// Keep save feedback above the sticky action area instead of overlapping it.
$('overridePanel').insertBefore($('overrideMessage'),$('overridePanel').querySelector('.detail-actions'));
let layoutFrame=0;
function scheduleLayout(){if(layoutFrame)return;layoutFrame=requestAnimationFrame(()=>{layoutFrame=0;const player=$('playerBar'),space=player.hidden?0:Math.ceil(player.getBoundingClientRect().height)+24;document.documentElement.style.setProperty('--player-space',space+'px');const viewport=$('listViewport'),top=viewport.getBoundingClientRect().top;viewport.style.setProperty('--list-height',Math.max(192,Math.floor(window.innerHeight-top-space-68))+'px');const active=topDialog();document.body.classList.toggle('modal-open',!!active);for(const panel of dialogIds.map($))panel.inert=!!active&&panel!==active;document.querySelector('main').inert=!!active;document.querySelector('.topbar').inert=false;$('settingsToggle').inert=!!active;for(const menu of document.querySelectorAll('.action-menu'))if(active)menu.open=false;})}
const layoutObserver=new ResizeObserver(scheduleLayout);for(const node of [$('playerBar'),$('settings'),document.querySelector('.toolbar'),document.querySelector('.heading'),$('jobPanel')])layoutObserver.observe(node);
const modalObserver=new MutationObserver(scheduleLayout);for(const node of [...dialogIds.map($),$('playerBar'),$('settings'),$('jobPanel')])modalObserver.observe(node,{attributes:true,attributeFilter:['hidden']});
window.addEventListener('resize',scheduleLayout);window.addEventListener('scroll',scheduleLayout,{passive:true});scheduleLayout();
// A single focus boundary includes the player and only the frontmost dialog.
document.addEventListener('keydown',event=>{const panel=topDialog();if(!panel||event.key!=='Tab')return;event.stopImmediatePropagation();const nodes=[...panel.querySelectorAll('button,input,select,textarea,summary,[tabindex]'),...($('playerBar').hidden?[]:$('playerBar').querySelectorAll('button,input,audio'))].filter(node=>!node.disabled&&!node.closest('[inert]')&&node.tabIndex>=0&&node.getClientRects().length);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(!nodes.includes(document.activeElement)){event.preventDefault();(event.shiftKey?last:first).focus()}else if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}},true);
